def _ensure_runtime_state():
    """Idempotently create every state field used by any callback."""
    if not hasattr(g, "prepared_events"):
        g.prepared_events = []
    if not hasattr(g, "prepared_date"):
        g.prepared_date = None
    if not hasattr(g, "active_batch"):
        g.active_batch = False
    if not hasattr(g, "holdings"):
        g.holdings = {}
    if not hasattr(g, "entry_submissions"):
        g.entry_submissions = {}
    if not hasattr(g, "pending_exits"):
        g.pending_exits = {}
    if not hasattr(g, "blacklist"):
        g.blacklist = set()
    if not hasattr(g, "last_open_date"):
        g.last_open_date = None
    if not hasattr(g, "last_close_date"):
        g.last_close_date = None
    if not hasattr(g, "diagnostics"):
        g.diagnostics = {"event_days": 0, "events": 0, "buy_submissions": 0,
                         "sell_submissions": 0, "skips": 0, "errors": 0}


def initialize(context):
    _ensure_runtime_state()
    set_benchmark(BENCHMARK)
    set_commission(commission_ratio=COMMISSION, min_commission=MIN_COMMISSION, type="STOCK")
    set_slippage(slippage=SLIPPAGE)
    run_daily(context, enter_batch_at_open, time="09:31")
    run_daily(context, manage_exits_at_close, time="15:00")


def before_trading_start(context, data):
    _ensure_runtime_state()
    today = _date_string(context)
    g.prepared_date = today
    g.prepared_events = []
    _reconcile_positions(context, today, final=False)
    raw = list(EVENTS_BY_DATE.get(today, ()))
    if not raw:
        return
    g.diagnostics["event_days"] += 1
    g.diagnostics["events"] += len(raw)
    if _batch_is_active(context):
        log.info("discard %s first-cover events on %s because batch is active", len(raw), today)
        return
    normalized = _normalize_effective_events(raw)
    static_ok = []
    for event in normalized:
        code, name, industry, signal, event_date, source_row_id = event
        bare = _bare(code)
        if signal not in ("\u4e70\u5165", "\u589e\u6301"):
            continue
        if code.endswith(".BJ") or bare.startswith("688"):
            continue
        if bare in SOE_FILTER:
            continue
        if _excluded_industry(industry):
            continue
        if code in g.blacklist:
            continue
        static_ok.append(event)
    g.diagnostics["static_ok"] = len(static_ok)
    if not static_ok:
        return
    codes = [event[0] for event in static_ok]
    try:
        tradable = filter_stock_by_status(
            stocks=codes,
            filter_type=["ST", "HALT", "DELISTING", "DELISTING_SORTING"],
            query_date=today,
        )
        tradable_bare = set(_bare(code) for code in (tradable or []))
        g.diagnostics["tradable"] = len(tradable_bare)
    except Exception as exc:
        log.warning("status filter failed on %s: %s", today, exc)
        g.diagnostics["errors"] += 1
        return
    listing = _listing_dates(codes)
    prepared = []
    for event in static_ok:
        code = event[0]
        if _bare(code) not in tradable_bare:
            continue
        listed_date = listing.get(_bare(code))
        if not _listed_for_365_days(listed_date, today):
            continue
        prepared.append(event)
    g.diagnostics["listing_records"] = len(listing)
    g.diagnostics["prepared"] = len(prepared)
    g.prepared_events = prepared


def handle_data(context, data):
    _ensure_runtime_state()


def after_trading_end(context, data):
    _ensure_runtime_state()
    _reconcile_positions(context, _date_string(context), final=True)


def enter_batch_at_open(context):
    _ensure_runtime_state()
    today = _date_string(context)
    if g.last_open_date == today:
        return
    g.last_open_date = today
    if g.prepared_date != today or not g.prepared_events:
        return
    if _batch_is_active(context):
        g.prepared_events = []
        return
    cash = _portfolio_cash(context)
    if cash < MIN_BATCH_CASH:
        g.prepared_events = []
        return
    codes = [event[0] for event in g.prepared_events]
    try:
        history = get_history(
            1,
            frequency="1m",
            field=["open", "high", "low", "close", "preclose", "volume"],
            security_list=codes,
            fq="pre",
            include=True,
            fill="nan",
            is_dict=True,
        )
    except Exception as exc:
        log.warning("09:31 completed-minute history failed: %s", exc)
        g.diagnostics["errors"] += 1
        history = {}
    selected = []
    industry_count = {}
    for event in g.prepared_events:
        code, name, industry, signal, event_date, source_row_id = event
        if code in g.blacklist:
            continue
        if _current_status_blocked(code, today):
            continue
        bar = _opening_bar(history, code)
        if bar is None:
            g.diagnostics["skips"] += 1
            continue
        price, preclose, volume = bar
        if price <= 0 or preclose <= 0 or volume <= 0:
            continue
        if _is_limit_up(code, price, preclose):
            continue
        if industry_count.get(industry, 0) >= MAX_INDUSTRY:
            continue
        selected.append((code, name, industry, price))
        industry_count[industry] = industry_count.get(industry, 0) + 1
        if len(selected) >= MAX_HOLD:
            break
    if not selected:
        g.prepared_events = []
        return
    _submit_two_round_buys(context, selected, cash, today)
    g.prepared_events = []
    g.active_batch = bool(g.entry_submissions) or _has_actual_positions(context)


def manage_exits_at_close(context):
    _ensure_runtime_state()
    today = _date_string(context)
    if g.last_close_date == today:
        return
    g.last_close_date = today
    _reconcile_positions(context, today, final=False)
    codes = [code for code in list(g.holdings) if _position_amount(code) > 0]
    if not codes:
        g.active_batch = bool(g.entry_submissions)
        return
    try:
        history = get_history(
            240,
            frequency="1m",
            field=["open", "high", "low", "close", "preclose", "volume"],
            security_list=codes,
            fq="pre",
            include=True,
            fill="nan",
            is_dict=True,
        )
    except Exception as exc:
        log.warning("15:00 completed-minute history failed: %s", exc)
        g.diagnostics["errors"] += 1
        history = {}
    for code in list(codes):
        position = get_position(code)
        amount = _attr_number(position, ("amount", "total_amount", "volume"), 0)
        enable = _attr_number(position, ("enable_amount", "closeable_amount", "can_sell"), amount)
        if amount <= 0:
            continue
        holding = g.holdings.get(code, {})
        if holding.get("entry_date") == today:
            continue
        pending = g.pending_exits.get(code)
        if pending is not None:
            if not _has_open_order(code) and enable > 0 and pending.get("last_submit_date") != today:
                _submit_exit(code, int(enable), pending.get("reason", "\u5230\u671f"), today)
            continue
        day = _completed_day(history, code)
        cost = _attr_number(position, ("avg_cost", "cost_basis"), holding.get("cost", 0.0))
        reason = None
        if day is not None and cost > 0:
            low_pct = day["low"] / cost - 1.0
            high_pct = day["high"] / cost - 1.0
            close_pct = day["close"] / cost - 1.0
            if low_pct <= STOP_LOSS:
                reason = "\u6b62\u635f"
            elif high_pct >= TAKE_PROFIT:
                if not _is_limit_up(code, day["close"], day["preclose"]):
                    reason = "\u6b62\u76c8"
            if reason is None:
                if close_pct <= STOP_LOSS:
                    reason = "\u6b62\u635f"
                elif close_pct >= TAKE_PROFIT and not _is_limit_up(code, day["close"], day["preclose"]):
                    reason = "\u6b62\u76c8"
        if reason is None:
            _advance_holding_age(holding, today)
            if int(holding.get("age", 0)) >= HOLD_DAYS:
                reason = "\u5230\u671f"
        if today == END_DATE and reason is None:
            reason = "\u672b\u65e5\u6e05\u4ed3"
        if reason is not None and enable > 0 and not _has_open_order(code):
            _submit_exit(code, int(enable), reason, today)
    _reconcile_positions(context, today, final=False)


def _normalize_effective_events(events):
    chosen = {}
    for event in events:
        code = event[0]
        current = chosen.get(code)
        if current is None or (event[4], int(event[5])) > (current[4], int(current[5])):
            chosen[code] = event
    return sorted(chosen.values(), key=lambda item: (int(item[5]), item[0]))


def _listing_dates(codes):
    result = {}
    try:
        info = get_stock_info(stocks=codes, field=["listed_date"])
    except Exception as exc:
        log.warning("get_stock_info failed: %s", exc)
        return result
    if isinstance(info, dict):
        for key, value in info.items():
            if isinstance(value, dict):
                result[_bare(key)] = value.get("listed_date") or value.get("list_date")
            else:
                result[_bare(key)] = getattr(value, "listed_date", None)
    return result


def _listed_for_365_days(listed_date, today):
    if not listed_date:
        return False
    try:
        listed = datetime.strptime(str(listed_date)[:10].replace("/", "-"), "%Y-%m-%d")
        current = datetime.strptime(today, "%Y-%m-%d")
        return (current - listed).days >= 365
    except Exception:
        return False


def _current_status_blocked(code, today):
    for query_type in ("ST", "HALT", "DELISTING_SORTING"):
        try:
            status = get_stock_status([code], query_type=query_type, query_date=today)
            if _status_value(status, code):
                return True
        except Exception as exc:
            log.warning("get_stock_status failed %s %s: %s", code, query_type, exc)
            return True
    return False


def _status_value(status, code):
    if isinstance(status, dict):
        if code in status:
            return bool(status[code])
        bare = _bare(code)
        for key, value in status.items():
            if _bare(key) == bare:
                return bool(value)
    return False


def _history_item(history, code):
    if history is None:
        return None
    if isinstance(history, dict):
        if code in history:
            return history[code]
        bare = _bare(code)
        for key, value in history.items():
            if _bare(key) == bare:
                return value
    return None


def _field_values(item, names):
    if item is None:
        return []
    for name in names:
        try:
            if isinstance(item, dict) and name in item:
                value = item[name]
            elif hasattr(item, "columns") and name in item.columns:
                value = item[name]
            elif getattr(getattr(item, "dtype", None), "names", None) and name in item.dtype.names:
                value = item[name]
            else:
                continue
            if hasattr(value, "tolist"):
                return value.tolist()
            if hasattr(value, "values"):
                raw = value.values
                return raw.tolist() if hasattr(raw, "tolist") else list(raw)
            if isinstance(value, (list, tuple)):
                return list(value)
            return [value]
        except Exception:
            continue
    return []


def _last_valid(values):
    for value in reversed(values or []):
        try:
            number = float(value)
            if number == number and number > 0:
                return number
        except Exception:
            continue
    return 0.0


def _opening_bar(history, code):
    item = _history_item(history, code)
    price = _last_valid(_field_values(item, ("open",)))
    preclose = _last_valid(_field_values(item, ("preclose", "preClose", "pre_close")))
    volume = _last_valid(_field_values(item, ("volume", "vol")))
    if price <= 0 or preclose <= 0:
        return None
    return price, preclose, volume


def _completed_day(history, code):
    item = _history_item(history, code)
    highs = [float(value) for value in _field_values(item, ("high",)) if _positive(value)]
    lows = [float(value) for value in _field_values(item, ("low",)) if _positive(value)]
    closes = [float(value) for value in _field_values(item, ("close", "price")) if _positive(value)]
    precloses = [float(value) for value in _field_values(item, ("preclose", "preClose", "pre_close")) if _positive(value)]
    if not highs or not lows or not closes:
        return None
    return {"high": max(highs), "low": min(lows), "close": closes[-1],
            "preclose": precloses[-1] if precloses else 0.0}


def _submit_two_round_buys(context, selected, cash, today):
    best_n = 1
    for try_n in range(min(len(selected), MAX_HOLD), 0, -1):
        per_cash = cash / try_n
        total_cost = 0.0
        count = 0
        for code, name, industry, price in selected[:try_n]:
            shares, cost = _size_order(per_cash, price)
            if shares < 100:
                continue
            total_cost += cost
            count += 1
        if count > 0 and total_cost <= cash and (cash - total_cost) / cash < 0.05:
            best_n = try_n
            break
    n_buy = min(best_n, len(selected))
    estimated_cash = float(cash)
    planned = set()
    per_cash = estimated_cash / n_buy if n_buy > 0 else estimated_cash
    for code, name, industry, price in selected[:n_buy]:
        shares, cost = _size_order(per_cash, price)
        if shares < 100 or cost > estimated_cash:
            continue
        if _submit_entry(code, name, industry, shares, cost, today):
            estimated_cash -= cost
            planned.add(code)
    if estimated_cash >= 3000.0 and len(planned) < MAX_HOLD:
        for code, name, industry, price in selected:
            if code in planned or len(planned) >= MAX_HOLD or estimated_cash < MIN_BATCH_CASH:
                continue
            shares, cost = _size_order(estimated_cash, price)
            if shares < 100 or cost > estimated_cash:
                continue
            if _submit_entry(code, name, industry, shares, cost, today):
                estimated_cash -= cost
                planned.add(code)


def _size_order(budget, visible_price):
    estimated_price = float(visible_price) * (1.0 + SLIPPAGE)
    shares = int(float(budget) / estimated_price / 100.0) * 100
    if shares < 100:
        return 0, 0.0
    amount = shares * estimated_price
    fee = max(amount * COMMISSION, MIN_COMMISSION)
    cost = amount + fee
    if cost > budget:
        shares = int((float(budget) - MIN_COMMISSION) / estimated_price / 100.0) * 100
        if shares < 100:
            return 0, 0.0
        amount = shares * estimated_price
        fee = max(amount * COMMISSION, MIN_COMMISSION)
        cost = amount + fee
    return shares, cost


def _submit_entry(code, name, industry, shares, estimated_cost, today):
    try:
        order_id = order(security=code, amount=int(shares))
    except Exception as exc:
        log.warning("buy order exception %s: %s", code, exc)
        g.diagnostics["errors"] += 1
        return False
    if order_id is None:
        log.info("buy rejected %s", code)
        return False
    g.entry_submissions[code] = {"name": name, "industry": industry,
                                  "shares": int(shares), "date": today,
                                  "estimated_cost": float(estimated_cost)}
    g.diagnostics["buy_submissions"] += 1
    return True


def _submit_exit(code, shares, reason, today):
    try:
        order_id = order(security=code, amount=-abs(int(shares)))
    except Exception as exc:
        log.warning("sell order exception %s %s: %s", code, reason, exc)
        g.diagnostics["errors"] += 1
        return False
    if order_id is None:
        log.info("sell rejected %s reason=%s", code, reason)
        return False
    g.pending_exits[code] = {"reason": reason, "last_submit_date": today}
    g.diagnostics["sell_submissions"] += 1
    return True


def _reconcile_positions(context, today, final=False):
    known = set(g.holdings) | set(g.entry_submissions) | set(g.pending_exits)
    for code in _portfolio_codes(context):
        known.add(code)
    for code in list(known):
        position = get_position(code)
        amount = _attr_number(position, ("amount", "total_amount", "volume"), 0)
        if amount > 0:
            if code not in g.holdings:
                submission = g.entry_submissions.get(code, {})
                g.holdings[code] = {
                    "entry_date": submission.get("date", today),
                    "last_age_date": submission.get("date", today),
                    "age": 0,
                    "industry": submission.get("industry", "UNKNOWN"),
                    "name": submission.get("name", code),
                    "cost": _attr_number(position, ("avg_cost", "cost_basis"), 0.0),
                }
            else:
                g.holdings[code]["cost"] = _attr_number(
                    position, ("avg_cost", "cost_basis"), g.holdings[code].get("cost", 0.0))
            g.entry_submissions.pop(code, None)
        else:
            pending = g.pending_exits.get(code)
            if pending is not None and not _has_open_order(code):
                if pending.get("reason") == "\u6b62\u635f":
                    g.blacklist.add(code)
                g.pending_exits.pop(code, None)
                g.holdings.pop(code, None)
            submission = g.entry_submissions.get(code)
            if submission is not None and not _has_open_order(code) and final:
                g.entry_submissions.pop(code, None)
    g.active_batch = bool(g.holdings or g.entry_submissions or g.pending_exits)


def _advance_holding_age(holding, today):
    entry = holding.get("entry_date")
    last_age = holding.get("last_age_date")
    if not entry or today <= entry or last_age == today:
        return
    holding["age"] = int(holding.get("age", 0)) + 1
    holding["last_age_date"] = today


def _has_open_order(code):
    try:
        orders = get_open_orders(security=code)
        if orders is None:
            return False
        if isinstance(orders, dict):
            return len(orders) > 0
        return len(list(orders)) > 0
    except Exception:
        return False


def _position_amount(code):
    try:
        return _attr_number(get_position(code), ("amount", "total_amount", "volume"), 0)
    except Exception:
        return 0.0


def _portfolio_codes(context):
    result = []
    positions = getattr(getattr(context, "portfolio", None), "positions", {}) or {}
    if isinstance(positions, dict):
        for key, position in positions.items():
            amount = _attr_number(position, ("amount", "total_amount", "volume"), 0)
            if amount > 0:
                result.append(_portable_code(key))
    return result


def _has_actual_positions(context):
    return bool(_portfolio_codes(context))


def _batch_is_active(context):
    return bool(g.active_batch or g.holdings or g.entry_submissions or
                g.pending_exits or _has_actual_positions(context))


def _portfolio_cash(context):
    try:
        return float(context.portfolio.cash)
    except Exception:
        return 0.0


def _attr_number(obj, names, default=0.0):
    for name in names:
        try:
            value = getattr(obj, name)
            if value is not None:
                return float(value)
        except Exception:
            continue
    return float(default or 0.0)


def _positive(value):
    try:
        number = float(value)
        return number == number and number > 0
    except Exception:
        return False


def _excluded_industry(industry):
    text = str(industry or "")
    return any(keyword in text for keyword in INDUSTRY_EXCLUDE)


def _is_limit_up(code, price, preclose):
    if not _positive(price) or not _positive(preclose):
        return False
    bare = _bare(code)
    threshold = 0.195 if bare.startswith(("300", "301")) else 0.095
    return float(price) / float(preclose) - 1.0 >= threshold


def _date_string(context):
    value = getattr(context, "current_dt", None)
    if value is None and hasattr(context, "blotter"):
        value = getattr(context.blotter, "current_dt", None)
    if hasattr(value, "strftime"):
        return value.strftime("%Y-%m-%d")
    return str(value)[:10]


def _bare(code):
    return str(code).split(".")[0].zfill(6)


def _portable_code(code):
    text = str(code)
    bare = _bare(text)
    if text.endswith(".BJ"):
        return bare + ".BJ"
    if bare.startswith("6"):
        return bare + ".SS"
    return bare + ".SZ"
